<?php $profile=$employeeWorkspace['profile'];?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=esc($profile['name'])?> · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'team',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><header class="page-header"><div><p class="eyebrow">EMPLOYEE WORKSPACE</p><h1><?=esc($profile['name'])?></h1><p><?=esc(($profile['position_name']?:'No position').' · '.($profile['department_name']?:'No department').' · '.ucfirst($profile['role']))?></p></div><?php if($admin):?><form method="get"><input type="hidden" name="route" value="employee"><select name="membership_id" onchange="this.form.submit()"><?php foreach($data['people'] as $person):?><option value="<?=$person['membership_id']?>" <?=$person['membership_id']==$selectedEmployeeId?'selected':''?>><?=esc($person['name'])?></option><?php endforeach;?></select></form><?php endif;?></header><section class="summary-grid"><?php foreach([[count($employeeWorkspace['schedule']),'Assigned shifts'],[count($employeeWorkspace['time_off']),'Time-off records'],[count($employeeWorkspace['credentials']),'Credentials'],[count($employeeWorkspace['callouts']),'Callouts']] as $item):?><article class="metric-card blue"><strong><?=$item[0]?></strong><span><?=$item[1]?></span></article><?php endforeach;?></section><section class="planning-grid"><article class="panel"><h2>Upcoming schedule</h2><?php foreach(array_slice($employeeWorkspace['schedule'],0,20) as $item):?><div class="planning-row"><span><strong><?=esc($item['shift_date'].' · '.date('g:i A',strtotime($item['starts_at'])))?></strong><small><?=esc($item['location_name'].' · '.$item['department_name'])?></small></span></div><?php endforeach;?></article><article class="panel"><h2>Availability</h2><?php foreach($employeeWorkspace['availability']['entries'] as $item):?><div class="planning-row"><span><strong><?=esc($item['entry_type']==='recurring'?'Weekday '.$item['weekday']:$item['applies_on'])?></strong><small><?=esc(ucfirst($item['availability']).' · '.ucfirst($item['status']))?></small></span></div><?php endforeach;?></article><article class="panel"><h2>Time off</h2><?php foreach($employeeWorkspace['time_off'] as $item):?><div class="planning-row"><span><strong><?=esc($item['starts_on'].' to '.$item['ends_on'])?></strong><small><?=esc(ucfirst($item['status']))?></small></span></div><?php endforeach;?></article><article class="panel"><h2>Credentials</h2><?php foreach($employeeWorkspace['credentials'] as $item):?><div class="planning-row"><span><strong><?=esc($item['credential_name'])?></strong><small><?=esc(ucfirst($item['status']).($item['expires_on']?' · expires '.$item['expires_on']:''))?></small></span></div><?php endforeach;?></article><article class="panel"><h2>Callout history</h2><?php foreach($employeeWorkspace['callouts'] as $item):?><div class="planning-row"><span><strong><?=esc($item['shift_date'])?></strong><small><?=esc(ucwords(str_replace('_',' ',$item['status'])))?></small></span></div><?php endforeach;?></article><article class="panel"><h2>Time entries</h2><?php foreach(array_slice($employeeWorkspace['time_entries'],0,20) as $item):?><div class="planning-row"><span><strong><?=esc($item['clocked_in_at'])?></strong><small><?=esc(ucfirst($item['status']).' · '.round((int)$item['worked_minutes']/60,2).' hrs')?></small></span></div><?php endforeach;?></article></section></main></body></html>
